from fastapi import FastAPI, HTTPException, WebSocket
from fastapi.testclient import TestClient
from fastapi.exceptions import RequestValidationError, ResponseValidationError, WebSocketRequestValidationError
from pydantic import BaseModel
import pytest

app = FastAPI()

class Item(BaseModel):
    id: int
    name: str

@app.get("/users/{user_id}")
async def get_user(user_id: str):
    # This should trigger RequestValidationError if we pass a non-int to a path param that expects int
    # But here user_id is str, so it won't. Let's change it to int.
    return {"user_id": user_id}

@app.get("/users_int/{user_id}")
async def get_user_int(user_id: int):
    return {"user_id": user_id}

@app.post("/items/")
async def create_item():
    # Trigger ResponseValidationError by returning something that doesn't match the response model
    # We need to specify response_model for this to happen
    return {"name": "Widget"} # missing 'id'

# To trigger ResponseValidationError, we need to use response_model
@app.post("/items_response/", response_model=Item)
async def create_item_response():
    return {"name": "Widget"} # missing 'id'

@app.websocket("/ws/{item_id}")
async def websocket_endpoint(websocket: WebSocket, item_id: int):
    await websocket.accept()
    await websocket.send_text(f"Item {item_id}")

client = TestClient(app)

def test_request_validation_error():
    try:
        client.get("/users_int/invalid")
    except RequestValidationError as e:
        print(f"RequestValidationError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

def test_response_validation_error():
    try:
        client.post("/items_response/")
    except ResponseValidationError as e:
        print(f"ResponseValidationError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

def test_websocket_validation_error():
    try:
        client.websocket("/ws/invalid")
    except WebSocketRequestValidationError as e:
        print(f"WebSocketRequestValidationError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    print("Testing RequestValidationError...")
    test_request_validation_error()
    print("\nTesting ResponseValidationError...")
    test_response_validation_error()
    print("\nTesting WebSocketRequestValidationError...")
    test_websocket_validation_error()
